        recipe.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        recipe.tags.some(tag => tag.toLowerCase().includes(searchQuery.toLowerCase()))
      )
    }

    // 模式过滤
    if (selectedMode !== 'all') {
      filtered = filtered.filter(recipe => recipe.mode === selectedMode)
