## ♿ 可访问性计算

### WCAG 对比度计算

```typescript
/**
 * 计算 WCAG 2.1 对比度
 */
function calculateContrast(color1: string, color2: string): number {
  const l1 = getRelativeLuminance(color1)
  const l2 = getRelativeLuminance(color2)

  const lighter = Math.max(l1, l2)
  const darker = Math.min(l1, l2)

  return (lighter + 0.05) / (darker + 0.05)
}

/**
 * 获取相对亮度
 */
function getRelativeLuminance(hex: string): number {
  const rgb = hexToRGB(hex)

  // 线性化
  const [r, g, b] = rgb.map(v => {
    const normalized = v / 255
    return normalized <= 0.03928
      ? normalized / 12.92
      : Math.pow((normalized + 0.055) / 1.055, 2.4)
  })

  // ITU-R BT.709 系数
  return 0.2126 * r + 0.7152 * g + 0.0722 * b
}

/**
 * 检查对比度是否符合 WCAG 标准
 */
function meetsWCAG(
  foreground: string,
  background: string,
  level: 'AA' | 'AAA' = 'AA'
): {
  normal: boolean  // 普通文本
  large: boolean   // 大文本
  contrast: number
} {
  const contrast = calculateContrast(foreground, background)

  const thresholds = {
    'AA': { normal: 4.5, large: 3 },
    'AAA': { normal: 7, large: 4.5 },
  }

  return {
    normal: contrast >= thresholds[level].normal,
    large: contrast >= thresholds[level].large,
    contrast,
  }
}
```

### 自动对比度优化

```typescript
/**
 * 调整颜色以满足对比度要求
 */
function adjustForContrast(
  foreground: { l: number; c: number; h: number },
  background: string,
  targetContrast: number = 4.5
): string {
  let { l, c, h } = foreground

  // 尝试调整亮度
  for (let i = 0; i < 100; i++) {
    const testColor = oklchToHex({ l, c, h })
    const contrast = calculateContrast(testColor, background)

    if (contrast >= targetContrast) {
      return testColor
    }

    // 根据背景亮度决定调整方向
    const bgLuminance = getRelativeLuminance(background)
    l = bgLuminance > 0.5 ? l - 0.01 : l + 0.01

    // 边界检查
    if (l < 0 || l > 1) break
  }

  return oklchToHex(foreground)
}
```

