## 📦 Registry Schema 设计

### 核心数据结构

```typescript
// src/types/registry.ts
export interface RegistryRecipe {
  // 基础信息
  id: string
  name: string
  description: string
  category: string
  version: string

  // 七轴参数
  config: {
    mode: ModeAxis
    base: BaseAxis
    accent: AccentAxis
    tone: ToneAxis
    density: DensityAxis
    motion: MotionAxis
    surface: SurfaceAxis
  }

  // 展示信息
  preview: {
    thumbnail: string
    screenshot?: string
    demoUrl?: string
    storybookUrl?: string
  }

  // 使用统计
  usage: {
    downloads: number
    rating: number
    ratingCount: number
    lastUsed: string
  }

  // 元数据
  metadata: {
    author: string
    created: string
    updated: string
    tags: string[]
    license: string
  }

  // 生成信息
  generated: {
    at: string
    by: string
    hash: string
  }
}

export interface RegistrySchema {
  version: string
  format: string
  generated: {
    at: string
    by: string
    hash: string
  }
  recipes: RegistryRecipe[]
  index: {
    byId: Record<string, RegistryRecipe>
    byCategory: Record<string, RegistryRecipe[]>
    byTag: Record<string, RegistryRecipe[]>
  }
}
```

